 const renderNodes=(nodes:any[],level:number,parent=''):React.ReactNode=><ul role={level===1?'tree':'group'} onKeyDown={level===1?onTreeKeyDown:undefined}>{nodes.map(node=>{const isDirectory=node.kind==='directory',closed=collapsed.has(node.path);return <li key={node.path} role="treeitem" aria-level={level} {...(isDirectory?{'aria-expanded':!closed}:{})}>{isDirectory?<><button type="button" data-tree-path={node.path} data-tree-parent={parent} data-tree-kind="directory" aria-expanded={!closed} disabled={disabled} onClick={()=>setCollapsed(current=>{const next=new Set(current);if(next.has(node.path))next.delete(node.path);else next.add(node.path);return next;})}>{closed?'▸':'▾'} {node.name}</button>{!closed&&<div role="group">{renderNodes(node.children,level+1,node.path)}</div>}</>:<div className="wb-file-tree-row"><button type="button" data-tree-path={node.path} data-tree-parent={parent} data-tree-kind="file" disabled={disabled} onClick={()=>onOpen(node.file)}><span>{node.path}</span><small>v{node.file.version} · {node.file.size} B</small></button>{(onRename||onDelete||onDownload)&&<div className="wb-file-tree-actions">{onRename&&<button type="button" disabled={disabled||actionsDisabled} onClick={()=>onRename(node.file)}>{t("重命名","Rename")}</button>}{onDelete&&<button type="button" disabled={disabled||actionsDisabled} onClick={()=>onDelete(node.file)}>{t("删除","Delete")}</button>}{onDownload&&<button type="button" disabled={disabled} onClick={()=>onDownload(node.file)}>{t("下载原始文件","Download Original File")}</button>}</div>}</div>}</li>;})}</ul>;
